#!/usr/bin/env bash
# ------------------------------------------------------------------
# 12s_pimelodidae: commands exactly as recorded in the workflow notes
# Source: Google Docs "Workflow ... (12s_pimelodidae)", id 1llCBo4XGWdhVPgf2GSkQw2FyFj8BdLhVFdUTHYsdIXs
#
# RECORD ONLY - do not run. Paths and file names are the ones used at
# the time, in a WSL working folder that contained the .gb file and an
# NCBI taxdump folder named 'taxdump'. To reproduce the analysis use
#   bash scripts/run_all_targets.sh 12s_pimelodidae
# ------------------------------------------------------------------

# Step 0 - GenBank query: see config/queries/query_12s_pimelodidae.txt

# Step 1 - GenBank to FASTA
obiconvert --skip-on-error --genbank -t taxdump 12s_pimelodidae.gb --fasta-output > 12s_pimelodidae.fasta

# Step 2 - unique taxids
grep -i -o 'taxid=[0-9]*' 12s_pimelodidae.fasta | cut -d '=' -f 2 | sort | uniq > 12s_pimelodidae_taxids.txt

# Step 3 - remove the target species and build the -i list
grep -v '1000982' 12s_pimelodidae_taxids.txt | awk '{printf "-i %s ", $1}'

# Step 4 - ecoPCR database
python /home/diogo/miniconda3/envs/ecoprimers_env/bin/ecoPCRFormat.py --fasta --taxonomy taxdump --name banco_12s_pimelodidae 12s_pimelodidae.fasta

# Step 5 - ecoPrimers, primer length N = 20..25 bp (-3 N -O N)
